export const icons={plus:'<path d="M12 5v14M5 12h14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',book:'<path d="M4 4h12a3 3 0 0 1 3 3v14H7a3 3 0 0 1-3-3V4Zm0 13h15M8 4v9m3-5h5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',leaf:'<path d="M20 3C9 2 2 6 5 15c8 5 15-1 15-12ZM5 20 16 8"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m2 10v-3a6 6 0 0 0-2-4"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>'};
export const icon=(name)=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
export const escapeHTML=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function shell(active){document.querySelector('#header').innerHTML=`<div class="nav-wrap"><a class="brand" href="index.html" aria-label="Смак — головна">${icon('book')}смак<span>твій кулінарний записник</span></a><nav aria-label="Головна навігація"><a href="index.html" class="${active==='collection'?'active':''}" ${active==='collection'?'aria-current="page"':''}>Мої рецепти</a><a href="index.html?favorites=1" class="${active==='favorites'?'active':''}">${icon('heart')} Обране</a></nav><a href="new.html" class="button nav-add">${icon('plus')}<span>Додати рецепт</span></a></div>`;document.querySelector('#footer').innerHTML=`<a class="brand footer-brand" href="index.html">${icon('book')}смак</a><p>Улюблені рецепти. Теплі спогади. Усе в одному місці.</p><span>З любов’ю до домашньої їжі</span>`;}
export function toast(message,error=false){let el=document.querySelector('#toast');if(!el){el=document.createElement('div');el.id='toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=message;el.className=error?'show error':'show';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.className='',4500);}
export function fatal(error){document.querySelector('main').innerHTML=`<div class="empty"><h1>Не вдалося відкрити записник</h1><p>${escapeHTML(error.message)}</p><a href="index.html" class="button">Спробувати ще раз</a></div>`;}
export const formatAmount=n=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:2}).format(n);
